import {textForLayer,layerArtwork,adoptLayerArtwork} from './layer-text.js';
import {installModules} from './module-ui.js';
import {modulesFor} from './modules.js';
import {SKINS,applySkin} from './skins.js';
import {layerCatalog,layerState,layerPatchSet,orderedLayers,reorderedLayers} from './layers.js';
import {THEMES,clone,newVariants,documentStats,contentCheck,titleArtwork} from './model.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let moduleUI;
let state=null,boot=null,view='edit',selection=null,layerSelection=null,saveTimer,renderTimer,toastTimer,dirty=false,saving=Promise.resolve(),revision=0,undoStack=[];
const heights={a:14000,b:14000,c:14000};
async function api(url,opts={}){const r=await fetch(url,{...opts,headers:{'Content-Type':'application/json',...opts.headers}});const data=await r.json();if(!r.ok)throw new Error(data.error||'操作失败');return data;}
const post=(url,data)=>api(url,{method:'POST',body:JSON.stringify(data)});
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.style.background=error?'#934f3f':'#263e32';t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,error?6500:3500);}
function guarded(fn){return async(...args)=>{try{await fn(...args);}catch(e){toast(e.message,true);}};}
function current(){return state.variants.find(v=>v.id===state.selected);}
function remember(){undoStack.push({document:clone(state.document),variants:clone(state.variants)});if(undoStack.length>35)undoStack.shift();}
function change(fn,rerender=true){remember();fn();dirty=true;revision++;$('#save-state').textContent='有修改 · 正在保存';clearTimeout(saveTimer);saveTimer=setTimeout(()=>save().catch(e=>toast(e.message,true)),700);if(rerender){clearTimeout(renderTimer);renderTimer=setTimeout(updatePreviews,100);}updateStats();}
async function save(){clearTimeout(saveTimer);if(!state||!dirty)return saving;const snapshot=clone(state),rev=revision;const previous=saving;saving=previous.catch(()=>{}).then(async()=>{try{const p=await api('/api/projects/'+snapshot.id,{method:'PUT',body:JSON.stringify(snapshot)});if(state?.id===snapshot.id&&revision===rev){dirty=false;state.updatedAt=p.updatedAt;$('#save-state').textContent='✓ 已保存到本机';}}catch(e){$('#save-state').textContent='保存失败 · 修改仍在页面';throw e;}});return saving;}
function updateStats(){const s=documentStats(state.document);$('#stats').textContent=`${modulesFor(state.document).length} 个模块  ·  ${s.characters} 字`;$('#source-name').textContent=state.sheetName||'本地工程';renderLayerList();}
function updatePreviews(){if(!state)return;$$('.preview-frame').forEach(f=>f.contentWindow?.postMessage({type:'render',project:state,variant:f.dataset.variant},location.origin));}
function scaleFrames(){if(!state)return;const stage=$('#canvases');for(const card of $$('.canvas-card')){const frame=card.querySelector('iframe'),wrap=card.querySelector('.frame-wrap');if(!frame)continue;const h=heights[frame.dataset.variant]||14000,mode=$('#canvas-zoom').value,available=Math.max(180,stage.clientWidth-48);const scale=mode==='whole'?Math.min(available/750,Math.max(100,stage.clientHeight-48)/h):mode==='fit'?available/750:Number(mode)/100;const old=Number(frame.dataset.scale)||scale;card.style.width=750*scale+'px';frame.style.transform='scale('+scale+')';frame.style.height=h+'px';frame.dataset.scale=scale;wrap.style.height=h*scale+'px';if(old!==scale)stage.scrollTop=stage.scrollTop/old*scale;$('#canvas-info').textContent=Math.round(scale*100)+'% · 750 px';}}
function renderCanvases(){const t=THEMES.find(t=>t.id===state.selected)||THEMES[0];$('#variant-tabs').innerHTML=THEMES.map(t=>`<button data-variant-tab="${t.id}" class="${t.id===state.selected?'active':''}"><b>${t.id.toUpperCase()}</b> ${t.id==='a'?'参考方案':t.id==='b'?'视觉探索一':'视觉探索二'}</button>`).join('');$('#canvases').className='canvases single-canvas';$('#canvases').innerHTML=`<section class="canvas-card active" data-variant="${t.id}"><div class="canvas-scroll"><div class="frame-wrap"><iframe class="preview-frame" title="${t.name}完整长图编辑画布" data-variant="${t.id}" src="/render.html"></iframe></div></div></section>`;const frame=$('.preview-frame');frame.addEventListener('load',()=>{frame.contentWindow.postMessage({type:'render',project:state,variant:t.id},location.origin);scaleFrames();});$('#canvases').scrollTop=0;scaleFrames();}
function selectVariant(id){moduleUI?.clear();state.selected=id;selection=null;layerSelection=null;renderInspector();renderCanvases();change(()=>{},false);}
function outline(){if(moduleUI){moduleUI.outline();return;}const d=state.document;const rows=[{id:'hero',text:'头图与标题',icon:'▧'},{id:'intro',text:'开篇导语',icon:'¶'},...d.blocks.filter(b=>['part','section','paragraph'].includes(b.kind)).map(b=>({id:b.id,text:b.text,icon:b.kind==='part'?'◈':b.kind==='section'?'☷':'¶',kind:b.kind})),{id:'outro',text:'结束语',icon:'◇'}];$('#outline').innerHTML=rows.map(b=>`<button data-block="${esc(b.id)}" class="${selection===b.id?'active ':''}${b.kind==='part'?'part-row':''}"><span class="outline-icon">${b.icon}</span><span>${esc(b.text.length>26?b.text.slice(0,26)+'…':b.text)}</span></button>`).join('');}
function range(label,key,min,max,step=1){const v=current();return `<label class="control"><span class="control-row">${label}<output>${v[key]??({titleArtWidth:100,chapterGap:40,titleGap:24}[key]??0)}</output></span><input type="range" data-setting="${key}" min="${min}" max="${max}" step="${step}" value="${v[key]??({titleArtWidth:100,chapterGap:40,titleGap:24}[key]??0)}"></label>`;}
function assetOptions(value){return '<option value="">无 / 默认素材</option>'+state.assets.filter(a=>a.role!=='reference'&&!a.role.startsWith('typography')).map(a=>`<option value="${esc(a.id)}" ${a.id===value?'selected':''}>${esc(a.name)}</option>`).join('');}
function renderInspector(){if(moduleUI?.selection()){const panel=moduleUI.inspector();if(panel){$('#variant-badge').textContent=current().id.toUpperCase();$('#inspector-content').innerHTML=panel;return;}}const v=current(),d=state.document;$('#variant-badge').textContent=v.id.toUpperCase();let edit='';if(selection&&!layerSelection){const b=d.blocks.find(b=>b.id===selection);const txt=selection==='hero'?d.title:selection==='intro'?d.intro:selection==='outro'?d.outro:b?.text;edit=`<section class="control-group"><h3>编辑内容 · 三方案同步</h3><label class="control">${selection==='hero'?'主标题':'文案'}<textarea id="block-text" rows="5">${esc(txt||'')}</textarea></label>${selection==='hero'?`<label class="control">副标题<input id="subtitle-text" value="${esc(d.subtitle)}"></label>`:''}${b?.kind==='dialogue'?`<label class="control">说话人<select id="speaker-select">${d.people.map(p=>`<option ${b.speaker===p.name?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`:''}${b?'<div class="mini-buttons"><button class="button" data-block-action="up">↑ 上移</button><button class="button" data-block-action="down">↓ 下移</button><button class="button" data-block-action="remove">删除</button></div>':''}<button class="button quiet" id="close-block" style="margin-top:8px">完成编辑</button></section>`;}
 $('#inspector-content').innerHTML=layerInspector()+edit+`<details class="global-settings" ${layerSelection?'':'open'}><summary>方案与 AI 设置</summary><section class="control-group"><h3>AI 标题艺术字</h3>${typographyControls(v)}</section><section class="control-group"><h3>主题配色</h3><div class="color-row"><label class="color-control"><input type="color" data-setting="primary" value="${v.primary}">主色</label><label class="color-control"><input type="color" data-setting="accent" value="${v.accent}">强调色</label></div><label class="lock-line"><input type="checkbox" id="lock-variant" ${v.locked?'checked':''}>锁定方案，生成时保留</label></section><section class="control-group"><h3>段落自动留白</h3><label class="lock-line"><input type="checkbox" id="auto-flow" ${v.autoFlow!==false?'checked':''}>移动后自动调整段落间距</label>${range('章节之间','chapterGap',16,160)}${range(v.id==='a'?'标题与对话框':'标题与正文','titleGap',0,120)}<p class="hint">松开拖动后自动避让，正文和后续章节顺延；导出使用相同留白。</p></section><section class="control-group"><h3>文字与排版</h3><label class="control">正文字体<select id="font-select"><option value="noto" ${v.fontId==='noto'?'selected':''}>Noto Sans CJK SC · 预览</option>${state.fonts.map(f=>`<option value="${f.id}" ${f.id===v.fontId?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label><label class="control">标题字体<select id="heading-font-select"><option value="" ${!v.headingFontId?'selected':''}>跟随正文字体</option>${[{id:'noto',name:'Noto Sans CJK SC · 预览'},...state.fonts].map(f=>`<option value="${f.id}" ${f.id===v.headingFontId?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label>${roleFontControls(v)}<button class="button quiet" id="add-font">＋ 添加项目指定字体</button>${v.fontId==='noto'?'<p class="font-warning">当前为开源预览字体。A 方案的字形还需用项目指定字体校对。</p>':''}${range('正文字号','fontSize',16,42)}${range('正文行距','lineHeight',1.2,2.4,.05)}${range('对话间距','gap',8,80)}</section><section class="control-group"><h3>可编辑文字字效</h3><div class="style-choices">${[['gold','金色立体'],['light','纯净亮白'],['outline','描边强调']].map(([id,n])=>`<button data-effect="${id}" class="style-choice ${v.titleEffect===id?'selected':''}">字<small>${n}</small></button>`).join('')}</div>${range('标题字号','titleSize',28,88)}${range('标题水平位置','titleX',-250,250)}${range('标题垂直位置','titleY',-250,250)}</section><section class="control-group"><h3>头图与独立人物</h3><label class="control">头图素材<select data-asset-setting="headerAssetId">${assetOptions(v.headerAssetId)}</select></label><label class="control">背景素材<select data-asset-setting="backgroundAssetId">${assetOptions(v.backgroundAssetId)}</select></label>${range('头图高度','headerHeight',400,1000)}${range('图片焦点 · 横向','headerX',0,100)}${range('图片焦点 · 纵向','headerY',0,100)}${range('图片缩放','headerScale',60,200)}<label class="control">独立人物 / 装饰<select data-asset-setting="overlayAssetId">${assetOptions(v.overlayAssetId)}</select></label>${v.overlayAssetId?range('人物横向位置','overlayX',0,100)+range('人物纵向位置','overlayY',0,100)+range('人物宽度','overlayWidth',10,100):''}<button class="button" id="ai-background">✦ 为本方案生成背景</button><p class="hint">生成结果先作为候选素材，采用后替换背景。</p></section><section class="control-group"><h3>人物与头像</h3>${d.people.map(p=>{const a=state.assets.find(a=>a.id===p.assetId);return `<button class="person-row" data-person="${p.id}">${a?`<img src="${a.url}" alt="">`:'◉'}<span>${esc(p.name)}</span><small>${p.role==='host'?'采访者':'受访者'} ›</small></button>`}).join('')}</section><section class="control-group"><button class="button" id="check-copy">✓ 核对原文与当前内容</button><button class="button quiet" id="undo">↶ 撤销最近修改</button></section></details>`;
 $('#current-font-note').textContent=v.fontId==='noto'?'开源预览字体 · 交付前核对项目用字':'已使用项目添加字体';
}
function assets(){ $('#asset-grid').innerHTML=state.assets.map(a=>`<button class="asset-tile" data-asset="${a.id}"><img src="${a.url}" alt="${esc(a.name)}" loading="lazy"><span>${esc(a.name)}</span></button>`).join('');}
function showProject(p){moduleUI?.clear();state=p;dirty=false;undoStack=[];selection=null;layerSelection=null;$('#project-name').value=p.name;$('#save-state').textContent='✓ 已保存到本机';updateStats();outline();assets();renderInspector();renderCanvases();}
function modal(title,html,actions=''){const m=$('#modal');$('#modal-content').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button data-close aria-label="关闭">×</button></div>${html}${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!m.open)m.showModal();}
function closeModal(){$('#modal').close();}
function fileBase64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(new Error('文件读取失败'));r.readAsDataURL(file);});}
function download(url,name){const a=document.createElement('a');a.href=url;if(name)a.download=name;a.click();}
async function poll(job){for(const id of ['open-project','import','new-sample'])$('#'+id).disabled=true;try{const line=$('#generation-status');line.hidden=false;line.classList.remove('error-line');line.textContent='✦ 正在处理素材，文案和已有方案仍可编辑…';while(true){await new Promise(r=>setTimeout(r,2000));const j=await api('/api/jobs/'+job.id);if(j.status==='running')continue;if(j.status!=='done'){line.textContent=j.error||'生成未完成，原方案已保留';line.classList.add('error-line');throw new Error(line.textContent);}const latest=await api('/api/projects/'+job.projectId);if(state.id===job.projectId){state.assets=latest.assets;assets();renderInspector();}line.textContent='✓ 素材已生成，可在项目素材中预览并采用';return j.result.asset;}}finally{for(const id of ['open-project','import','new-sample'])$('#'+id).disabled=false;}}
async function generateBackground(variant,prompt='',adopt=false){await save();const v=state.variants.find(v=>v.id===variant);if(v.locked)throw new Error('方案已锁定，请先解锁');const source=state.assets.find(a=>a.id===v.headerAssetId)||state.assets.find(a=>a.role==='header');if(!source)throw new Error('请先上传并指定头图素材');const job=await post('/api/projects/'+state.id+'/ai',{kind:'background',variant,assetId:source.id,prompt});const a=await poll(job);if(adopt&&!v.locked){change(()=>v.backgroundAssetId=a.id);renderInspector();await save();}return a;}
async function ensureCutout(variant){
 const v=state.variants.find(v=>v.id===variant);if(v.overlayAssetId||!boot.cutoutConfigured)return;
 const source=state.assets.find(a=>a.id===v.headerAssetId)||state.assets.find(a=>a.role==='header');if(!source)return;
 let a=state.assets.find(a=>a.role==='cutout'&&a.sourceAssetId===source.id);
 if(!a){await save();const job=await post('/api/projects/'+state.id+'/ai',{kind:'cutout',variant,assetId:source.id});a=await poll(job);}
 if(v.locked)return;change(()=>{v.overlayAssetId=a.id;v.overlayWidth=100;v.overlayX=55;v.overlayY=36;});renderInspector();await save();
}
function assetDialog(id){const a=state.assets.find(a=>a.id===id);if(!a)return;if(a.role==='typography-reference'){change(()=>current().titleReferenceAssetId=a.id);renderInspector();return typographyDialog();}if(a.role.startsWith('typography'))return typographyPreview(a);modal(a.name,`<img class="asset-preview" src="${a.url}" alt="${esc(a.name)}"><p class="hint">${a.width} × ${a.height} px · 采用到当前 ${state.selected.toUpperCase()} 方案</p><label class="control">用途<select id="asset-use"><option value="newLayer">添加为独立图片 / Logo 图层</option><option value="headerAssetId">头图原图</option><option value="backgroundAssetId" ${a.role==='background'?'selected':''}>背景</option><option value="overlayAssetId" ${a.role==='cutout'?'selected':''}>独立人物 / 装饰</option></select></label>`,`<button class="button" id="cutout-asset" data-id="${a.id}">智能抠图</button><button class="button primary" id="adopt-asset" data-id="${a.id}">采用素材</button>`);}
$('#canvases').addEventListener('click',e=>{const t=e.target.closest('[data-select],[data-edit]');if(!t)return;selectVariant(t.dataset.select||t.dataset.edit);if(t.dataset.edit){view='edit';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));renderCanvases();}});
$('#canvases').addEventListener('keydown',e=>{if(e.key==='Enter')e.target.closest('[data-select]')?.click();});
$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;$$('[data-view]').forEach(x=>x.classList.toggle('active',x===b));renderCanvases();});
$$('[data-left-tab]').forEach(b=>b.onclick=()=>{$$('[data-left-tab]').forEach(x=>x.classList.toggle('active',x===b));$('#outline-panel').hidden=b.dataset.leftTab!=='outline';$('#assets-panel').hidden=b.dataset.leftTab!=='assets';$('#layers-panel').hidden=b.dataset.leftTab!=='layers';});
$('#outline').onclick=e=>{const b=e.target.closest('[data-block]');if(!b)return;selection=b.dataset.block;layerSelection=null;outline();renderInspector();$$('.preview-frame').filter(f=>f.dataset.variant===state.selected).forEach(f=>f.contentWindow.postMessage({type:'scroll-block',id:selection},location.origin));};
window.addEventListener('message',e=>{if(e.origin!==location.origin)return;const m=e.data;if(m?.type==='delete-layer'&&state?.selected===m.variant){deleteSelectedLayer(m.id);}if(m?.type==='layer-warning')toast(m.message,true);if(m?.type==='undo-layers')undo();if(m?.type==='select-layer'){moduleUI?.exit();layerSelection=m.id;selection=null;renderLayerList();renderInspector();}if(m?.type==='change-layer'){if(state.selected===m.variant)applyLayerPatch(m.id,m.patch);}
 if(m?.type==='render-height'){heights[m.variant]=m.height;scaleFrames();}if(m?.type==='move-element'){const v=state.variants.find(v=>v.id===m.variant);if(v&&!v.locked){change(()=>Object.assign(v,m.settings));renderInspector();}}if(m?.type==='select-block'){layerSelection=null;state.selected=m.variant;selection=m.id;$$('.canvas-card').forEach(c=>c.classList.toggle('active',c.dataset.variant===m.variant));outline();renderInspector();}if(m?.type==='scroll-position'){const card=$(`.canvas-card[data-variant="${m.variant}"]`);if(card)$('#canvases').scrollTop=m.top*Number(card.querySelector('iframe').dataset.scale||1);}});
new ResizeObserver(scaleFrames).observe($('#canvases'));
$('#inspector-content').addEventListener('input',e=>{const t=e.target;if(t.dataset.setting){change(()=>current()[t.dataset.setting]=t.type==='color'?t.value:Number(t.value));t.closest('label').querySelector('output')?.replaceChildren(document.createTextNode(t.value));}if(t.id==='block-text'){change(()=>{if(selection==='hero')state.document.title=t.value;else if(selection==='intro')state.document.intro=t.value;else if(selection==='outro')state.document.outro=t.value;else{const b=state.document.blocks.find(b=>b.id===selection);if(b)b.text=t.value;}});outline();updateTypographyStatus();}if(t.id==='subtitle-text')change(()=>state.document.subtitle=t.value);});
$('#inspector-content').addEventListener('change',e=>{const t=e.target;if(t.dataset.assetSetting){change(()=>current()[t.dataset.assetSetting]=t.value);renderInspector();}if(t.id==='font-select'){change(()=>current().fontId=t.value);renderInspector();}if(t.id==='heading-font-select'){change(()=>current().headingFontId=t.value);renderInspector();}if(t.id==='auto-flow')change(()=>current().autoFlow=t.checked);if(t.id==='lock-variant')change(()=>current().locked=t.checked);if(t.id==='speaker-select'){change(()=>{const b=state.document.blocks.find(b=>b.id===selection);const old=b.speaker;if(b.text.startsWith(old+'：')||b.text.startsWith(old+':'))b.text=t.value+'：'+b.text.slice(old.length+1);b.speaker=t.value;});renderInspector();}});
$('#inspector-content').addEventListener('click',guarded(async e=>{const t=e.target.closest('button');if(!t)return;
 if(t.id==='clean-typography'){await refineTypography(t);return;}if(t.id==='upload-typography-reference')chooseTypographyReference(false);
 if(t.id==='clear-typography-reference'){change(()=>current().titleReferenceAssetId='');renderInspector();}
 if(t.id==='ai-typography')typographyDialog();
 if(t.id==='native-title'){change(()=>current().titleArtAssetId='');renderInspector();}
 if(t.dataset.typography)typographyPreview(state.assets.find(a=>a.id===t.dataset.typography));
 if(t.dataset.effect){change(()=>{current().titleEffect=t.dataset.effect;current().titleArtAssetId='';});renderInspector();}
 if(t.id==='close-block'){selection=null;outline();renderInspector();}
 if(t.dataset.blockAction){const i=state.document.blocks.findIndex(b=>b.id===selection);if(i<0)return;if(t.dataset.blockAction==='remove'){modal('删除内容模块','<p class="hint">此操作会同步影响三套方案，可以撤销。</p>','<button class="button" data-close>取消</button><button class="button primary" id="confirm-delete-block">删除模块</button>');return;}change(()=>{const j=t.dataset.blockAction==='up'?i-1:i+1;if(j>=0&&j<state.document.blocks.length)[state.document.blocks[i],state.document.blocks[j]]=[state.document.blocks[j],state.document.blocks[i]];});outline();}
 if(t.id==='add-font'){modal('添加项目指定字体','<p class="hint">字体仅在本机工程中使用，工程包不会携带字体文件。</p><label class="checkbox-row"><input id="font-confirm" type="checkbox">我确认该字体允许用于本项目及本机网页编辑、图片导出。</label>','<button class="button primary" id="choose-font">选择字体文件</button>');}
 if(t.id==='ai-background'){modal('生成背景候选','<p class="hint">会将当前头图发送到已配置的图像服务，并消耗服务额度。请仅使用已公开素材。生成后可预览、采用。</p><label class="control">补充视觉方向<textarea id="ai-prompt" placeholder="例如：深蓝与银白，角色区域留白，装饰克制"></textarea></label>','<button class="button" data-close>取消</button><button class="button primary" id="run-background">生成背景</button>');}
 if(t.dataset.person){const p=state.document.people.find(p=>p.id===t.dataset.person);modal('头像 · '+p.name,`<label class="control">来源素材<select id="person-asset">${assetOptions(p.assetId)}</select></label><label class="control">横向焦点<input id="person-x" type="range" min="0" max="100" value="${p.crop.x}"></label><label class="control">纵向焦点<input id="person-y" type="range" min="0" max="100" value="${p.crop.y}"></label><label class="control">放大倍率<input id="person-zoom" type="range" min="1" max="5" step=".1" value="${p.crop.zoom}"></label><div class="portrait-preview" style="height:140px;display:grid;place-items:center"><img id="person-preview" style="width:110px;height:110px;border-radius:50%;object-fit:cover" src="${state.assets.find(a=>a.id===p.assetId)?.url||''}" alt="头像预览"></div><p class="hint">头像同时应用到全部方案；保留人物原图。</p>`,`<button class="button primary" id="save-person" data-id="${p.id}">应用头像</button>`);}
 if(t.id==='check-copy'){const missing=contentCheck(state);modal('原文核对',`<p>${missing.length?`有 ${missing.length} 段与导入原文不一致，请核对修改或删除是否符合需求。`:'✓ 标题、导语、章节和问答与导入原文一致。'}</p><div class="audit-box">${missing.map(s=>`<p><b>${esc(s.cell)}</b> ${esc(s.text)}</p>`).join('')||'没有检测到原文遗漏或改写。'}</div><p class="hint">字体、人物对应关系和视觉效果仍需设计师检查。</p>`);}
 if(t.id==='undo')undo();
}));
function undo(){const old=undoStack.pop();if(!old){toast('没有可撤销的修改');return;}state.document=old.document;state.variants=old.variants;dirty=true;revision++;updateStats();outline();renderInspector();updatePreviews();save().catch(e=>toast(e.message,true));}
$('#asset-grid').onclick=e=>{const t=e.target.closest('[data-asset]');if(t)assetDialog(t.dataset.asset);};
