$('#export').onclick=()=>modal('导出长图',`<label class="control">方案<select id="export-variant">${THEMES.map(t=>`<option value="${t.id}" ${state.selected===t.id?'selected':''}>${t.id.toUpperCase()} · ${t.name}</option>`).join('')}</select></label><label class="control">图片格式<select id="export-format"><option value="png">PNG · 清晰文字</option><option value="jpg">JPG · 较小体积</option></select></label><label class="checkbox-row"><input id="export-slices" type="checkbox">同时按 2400 像素高度切片（ZIP）</label><p class="font-warning">导出宽度 750 px。当前使用${current().fontId==='noto'?'开源预览字体，请核对项目规定用字。':'项目添加字体，请核对字符显示。'} 切片采用固定高度，可能跨越段落。</p>`,`<button class="button" data-close>取消</button><button class="button primary" id="run-export">导出图片</button>`);
$('#modal').addEventListener('click',guarded(async e=>{const t=e.target.closest('button');if(!t)return;if(t.hasAttribute('data-close'))closeModal();
 if(t.dataset.openProject){showProject(await api('/api/projects/'+t.dataset.openProject));closeModal();}
 if(t.id==='restore-project')$('#project-input').click();
 if(t.id==='choose-font'){if(!$('#font-confirm').checked)throw new Error('请先确认字体可用于本项目');$('#font-input').click();}
 if(t.id==='confirm-delete-block'){change(()=>state.document.blocks=state.document.blocks.filter(b=>b.id!==selection));selection=null;outline();renderInspector();closeModal();}
 if(t.id==='insert-block'){const text=$('#new-text').value;if(!text.trim())throw new Error('请填写文案或图片说明');const kind=$('#new-kind').value,sp=$('#new-speaker').value,id=crypto.randomUUID(),assetId=$('#new-image').value;if(kind==='image'&&!assetId)throw new Error('请选择图片');change(()=>{let i=state.document.blocks.findIndex(b=>b.id===selection);if(i<0)i=state.document.blocks.length-1;state.document.blocks.splice(i+1,0,{id,kind,text:kind==='dialogue'&&!text.startsWith(sp+'：')?sp+'：'+text:text,speaker:kind==='dialogue'?sp:'',assetId,group:state.document.blocks[i]?.group||''});});selection=id;outline();renderInspector();closeModal();}
 if(t.id==='adopt-asset'){if(current().locked)throw new Error('请先解锁方案');const use=$('#asset-use').value;if(use==='newLayer')addFreeImage(t.dataset.id);else change(()=>current()[use]=t.dataset.id);closeModal();renderInspector();toast('已应用素材');}
 if(t.id==='cutout-asset'){await save();const job=await post('/api/projects/'+state.id+'/ai',{kind:'cutout',assetId:t.dataset.id,variant:state.selected});closeModal();const a=await poll(job);assetDialog(a.id);}
 if(t.id==='save-person'){const id=t.dataset.id,aid=$('#person-asset').value,crop={x:Number($('#person-x').value),y:Number($('#person-y').value),zoom:Number($('#person-zoom').value)};change(()=>{const p=state.document.people.find(p=>p.id===id);p.assetId=aid;p.crop=crop;});closeModal();renderInspector();}
 if(t.id==='modal-upload-reference')chooseTypographyReference(true);
 if(t.id==='run-typography'){const variant=state.selected,assetId=$('#typography-reference').value,prompt=$('#typography-prompt').value;change(()=>current().titleReferenceAssetId=assetId,false);await save();const job=await post('/api/projects/'+state.id+'/ai',{kind:'typography',variant,assetId,prompt});closeModal();const a=await poll(job);typographyPreview(a,variant);}
 if(t.id==='adopt-typography'){const a=state.assets.find(a=>a.id===t.dataset.id),v=state.variants.find(v=>v.id===t.dataset.variant);if(v.locked)throw new Error('请先解锁方案');if(a?.role!=='typography'||a.targetText!==state.document.title)throw new Error('当前标题已变化，请重新生成');if(!$('#typography-checked').checked)throw new Error('请逐字核对候选后勾选确认');change(()=>{v.titleArtAssetId=a.id;v.titleArtWidth=100;v.titleArtX=0;v.titleArtY=0;});renderInspector();closeModal();await save();toast('已采用独立艺术字图层');}
 if(t.id==='run-background'){const prompt=$('#ai-prompt').value,variant=state.selected;closeModal();const a=await generateBackground(variant,prompt);assetDialog(a.id);}
 if(t.id==='run-generate'){const ai=$('#enhance-ai').checked;closeModal();change(()=>{const defs=newVariants();for(let i=0;i<state.variants.length;i++){const v=state.variants[i];if(!v.locked)state.variants[i]={...defs[i],...(v.designProfile?{designProfile:v.designProfile,primary:v.primary,fontSize:v.fontSize,lineHeight:v.lineHeight,gap:v.gap,titleSize:v.titleSize,headerHeight:v.headerHeight,headerX:v.headerX,headerY:v.headerY,headerScale:v.headerScale}:{}),fontId:v.fontId,headingFontId:v.headingFontId||'',titleFontId:v.titleFontId||'',numberFontId:v.numberFontId||'',skinId:v.skinId||'original',...(v.skinId&&v.skinId!=='original'?{primary:v.primary,accent:v.accent}:{}),headerAssetId:v.headerAssetId,overlayAssetId:v.overlayAssetId,overlayX:v.overlayX,overlayY:v.overlayY,overlayWidth:v.overlayWidth,autoFlow:v.autoFlow!==false,chapterGap:v.chapterGap??40,titleGap:v.titleGap??24,modules:Object.fromEntries(modulesFor(state.document).map(m=>[m.id,{layout:v.id==='a'?'default':v.id==='b'?'cards':'compact',...(v.modules?.[m.id]||{})}])),hiddenBlocks:v.hiddenBlocks||[],overrides:v.overrides||{},layers:v.layers||{},layerOrder:v.layerOrder||[],customLayers:v.customLayers||[],titleReferenceAssetId:v.titleReferenceAssetId||'',titleArtAssetId:v.titleArtAssetId||'',titleArtWidth:v.titleArtWidth??100,titleArtX:v.titleArtX??0,titleArtY:v.titleArtY??0};}});renderInspector();updatePreviews();await save();if(ai){$('#generate').disabled=true;try{for(const id of ['b','c'])if(!state.variants.find(v=>v.id===id).locked){await ensureCutout(id);await generateBackground(id,'',true);}toast('三套方案已完成，AI 背景需要人工检查');}finally{$('#generate').disabled=false;}}else toast('三套模板方案已生成，未调用 AI');}
 if(t.id==='run-export'){t.disabled=true;t.textContent='正在渲染…';try{await save();const fmt=$('#export-format').value,slices=$('#export-slices').checked;const r=await post('/api/projects/'+state.id+'/export',{variant:$('#export-variant').value,format:fmt,slices});download(r.url,state.name+(slices?'.zip':'.'+fmt));closeModal();toast(`已导出 750 × ${r.height} px${r.slices?' · '+r.slices+' 张切片':''}`);}finally{t.disabled=false;t.textContent='导出图片';}}
}));
$('#modal').addEventListener('input',e=>{if(!['person-x','person-y','person-zoom','person-asset'].includes(e.target.id))return;const img=$('#person-preview');img.src=state.assets.find(a=>a.id===$('#person-asset').value)?.url||'';img.style.objectPosition=$('#person-x').value+'% '+$('#person-y').value+'%';img.style.transform='scale('+$('#person-zoom').value+')';img.parentElement.style.overflow='hidden';});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();save().then(()=>toast('已保存')).catch(e=>toast(e.message,true));}if((e.ctrlKey||e.metaKey)&&e.key==='z'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();undo();}});
async function init(){boot=await api('/api/bootstrap');const p=boot.projects.length?await api('/api/projects/'+boot.projects[0].id):await post('/api/sample',{});showProject(p);for(const job of boot.jobs.filter(j=>j.projectId===p.id))poll(job).catch(e=>toast(e.message,true));}
moduleUI=installModules({state:()=>state,current,clearSelection:()=>{selection=null;layerSelection=null;},outline,inspector:renderInspector,change,assetOptions,focusLayer,guard:guarded,toast,modal,close:closeModal,save,post,show:showProject,undo});
init().catch(e=>{$('#save-state').textContent='打开失败';$('#canvases').innerHTML='<p class="preview-placeholder">'+esc(e.message)+'<br>请检查本地服务后刷新。</p>';toast(e.message,true);});

function typographyControls(v){const status=titleArtwork(state,v);const candidates=state.assets.filter(a=>a.role==='typography'&&!a.targetLayerId&&a.targetText===state.document.title);return `${typographyReferenceControl(v)}<button class="button primary" id="ai-typography">✦ AI 生成标题艺术字</button><p id="typography-status" class="hint">${status.stale?'标题已修改，旧艺术字已停用。请重新生成或切回文字。':status.asset?'已采用 AI 艺术字。文字变化后需重新生成。':'用主标题生成透明字效图，原文保留，可拖动与缩放。'}</p>${status.asset?'<button class="button" id="clean-typography">精修抠图 · 清理字内残底</button><p class="hint">从原始候选重新提取，不重新生成文字；可撤销。</p>':''}${v.titleArtAssetId?'<button class="button" id="native-title">切回可编辑文字</button>'+range('艺术字宽度 %','titleArtWidth',30,130)+range('艺术字横向偏移','titleArtX',-250,250)+range('艺术字纵向偏移','titleArtY',-250,250):''}${candidates.length?'<div class="typography-candidates">'+candidates.map(a=>`<button data-typography="${a.id}" title="预览并采用"><img src="${a.url}" alt="${esc(a.name)}"></button>`).join('')+'</div>':''}`;}
function updateTypographyStatus(){const el=$('#typography-status');if(el){const s=titleArtwork(state,current());el.textContent=s.stale?'标题已修改，旧艺术字已停用。请重新生成或切回文字。':s.asset?'已采用 AI 艺术字。文字变化后需重新生成。':'用主标题生成透明字效图，原文保留，可拖动与缩放。';}}
function typographyDialog(){if(current().locked)throw new Error('请先解锁方案');if(!boot.aiConfigured)throw new Error('请先配置图像生成服务');const ref=selectedTypographyReference(current());modal('AI 标题艺术字',`<p class="hint">优先参考上传图片的字形、笔锋、倾斜与配色生成 1 张候选。主标题原文保留；副标题仍可编辑。再次生成可积累不同候选。</p><label class="control">主标题原文<textarea readonly rows="3">${esc(state.document.title)}</textarea></label><label class="control">艺术字参考图<select id="typography-reference">${state.assets.filter(a=>a.role!=='typography-raw').map(a=>`<option value="${a.id}" ${a.id===ref?.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><div id="modal-reference-preview">${referencePreview(ref)}</div><button class="button" id="modal-upload-reference">＋ 上传 / 更换艺术字参考图</button><label class="control">字效设计方向<textarea id="typography-prompt" rows="3" placeholder="例如：参考图中的锐利笔锋、金色渐变和前倾字形，不加粗描边"></textarea></label><p class="hint">调用已配置图像服务，发送标题与所选参考图并消耗额度。仅使用已公开素材。生成后逐字核对再采用；艺术字为图片，改字需重新生成。</p>`,'<button class="button" data-close>取消</button><button class="button primary" id="run-typography">生成艺术字候选</button>');}
function typographyPreview(a,variant=state.selected){if(!a)return;if(a.targetLayerId)return layerTypographyPreview(a,variant);const usable=a.role==='typography'&&a.targetText===state.document.title;modal('艺术字候选 · '+variant.toUpperCase(),`<div class="typography-preview"><img src="${a.url}" alt="艺术字候选，待人工核对"></div><label class="control">生成时的标题原文<textarea readonly rows="3">${esc(a.targetText)}</textarea></label><p class="hint">${a.role==='typography-raw'?esc(a.extractError||'原始生成图，尚未提取为透明字效，不能直接采用。'):!usable?'当前标题与候选不一致，请按新文案重新生成。':'透明背景，可独立拖动、缩放；请对照原文检查错字、漏字和标点。'}</p>${usable?'<label class="checkbox-row"><input id="typography-checked" type="checkbox">已逐字核对，文字准确完整</label>':''}`,`<button class="button" data-close>暂不采用</button>${usable?`<button class="button primary" id="adopt-typography" data-id="${a.id}" data-variant="${variant}">采用到 ${variant.toUpperCase()} 方案</button>`:''}`);}

let referenceUploadContext=null;
function selectedTypographyReference(v){return state.assets.find(a=>a.id===v.titleReferenceAssetId)||state.assets.find(a=>a.role==='reference')||state.assets.find(a=>a.role==='header');}
function referencePreview(a){return a?`<img class="typography-reference-image" src="${a.url}" alt="当前艺术字参考图"><p class="hint">${esc(a.name)}</p>`:'<p class="hint">尚未选择参考图</p>';}
function typographyReferenceControl(v){const ref=state.assets.find(a=>a.id===v.titleReferenceAssetId);return `<div id="typography-reference-drop" class="reference-drop"><button class="reference-upload" id="upload-typography-reference">${ref?`<img src="${ref.url}" alt="已选艺术字参考图"><span>更换艺术字参考图</span>`:'<b>＋ 放入艺术字参考图</b><span>点击上传，或拖入 PNG / JPG / WebP</span>'}</button></div><p class="hint">${ref?'优先参考这张图的字形、笔锋、倾斜与色彩。':'可上传局部字效截图，生成时保留当前标题原文。未上传时使用原稿参考。'}</p>${ref?'<button class="button quiet" id="clear-typography-reference">移除专用参考，改用原稿</button>':''}`;}
function chooseTypographyReference(inModal){if(current().locked)throw new Error('请先解锁方案');referenceUploadContext={projectId:state.id,variant:state.selected,inModal};$('#typography-reference-input').click();}
async function uploadTypographyReference(file,context){if(!file)return;if(file.size>25*1024*1024)throw new Error('参考图不能超过 25MB');if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('请选择 PNG、JPG 或 WebP 参考图');const a=await post('/api/projects/'+context.projectId+'/assets',{name:file.name,base64:await fileBase64(file),role:'typography-reference'});if(state.id!==context.projectId){toast('参考图已保存在原工程素材库');return;}state.assets.push(a);const v=state.variants.find(v=>v.id===context.variant);if(v.locked){assets();toast('方案已锁定，参考图已保留在素材库');return;}change(()=>v.titleReferenceAssetId=a.id);assets();renderInspector();await save();if(context.inModal&&$('#modal').open&&$('#typography-reference')){const option=document.createElement('option');option.value=a.id;option.textContent=a.name;$('#typography-reference').append(option);$('#typography-reference').value=a.id;$('#modal-reference-preview').innerHTML=referencePreview(a);}toast('艺术字参考图已保存，生成时优先使用');}
$('#typography-reference-input').onchange=guarded(async e=>{const f=e.target.files[0],context=referenceUploadContext;e.target.value='';if(f&&context)await uploadTypographyReference(f,context);});
$('#inspector-content').addEventListener('dragover',e=>{const area=e.target.closest('#typography-reference-drop');if(area){e.preventDefault();e.dataTransfer.dropEffect='copy';area.classList.add('dragging');}});
$('#inspector-content').addEventListener('dragleave',e=>e.target.closest('#typography-reference-drop')?.classList.remove('dragging'));
$('#inspector-content').addEventListener('drop',guarded(async e=>{const area=e.target.closest('#typography-reference-drop');if(!area)return;e.preventDefault();area.classList.remove('dragging');if(current().locked)throw new Error('请先解锁方案');await uploadTypographyReference(e.dataTransfer.files[0],{projectId:state.id,variant:state.selected,inModal:false});}));
$('#modal').addEventListener('change',e=>{if(e.target.id==='typography-reference')$('#modal-reference-preview').innerHTML=referencePreview(state.assets.find(a=>a.id===e.target.value));});

function selectedLayer(){return layerCatalog(state,current()).find(l=>l.id===layerSelection);}
function deleteSelectedLayer(id=layerSelection){
 if(!state)return;const v=current(),l=layerCatalog(state,v).find(l=>l.id===id);if(!l)return;
 if(v.locked||layerState(v,id).locked){toast('请先解锁方案或图层',true);return;}
 change(()=>{v.layers||={};if(l.custom){v.customLayers=v.customLayers.filter(x=>x.id!==id);delete v.layers[id];}else v.layers[id]={...layerState(v,id),deleted:true};layerSelection=null;selection=null;});
 renderInspector();toast('已删除图层，可点击撤销恢复');
}
$('#delete-layer-toolbar').onclick=()=>deleteSelectedLayer();
$('#undo-toolbar').onclick=undo;
window.addEventListener('keydown',e=>{if(!state||$('#modal').open||e.defaultPrevented||e.target.closest?.('input,textarea,select,[contenteditable="true"]'))return;if(['Delete','Backspace'].includes(e.key)&&layerSelection){e.preventDefault();deleteSelectedLayer();}});
$('#change-skin').onclick=guarded(()=>{
 const v=current(),theme=THEMES.find(t=>t.id===v.id);if(v.locked)throw new Error('请先解锁方案');
 modal('一键换皮 · '+v.id.toUpperCase()+' 方案',`<p class="hint">点击皮肤即可应用到当前方案。文案、图片、字体和图层位置保留；照片与 AI 艺术字图片保持原色。换皮后可撤销。</p><div class="skin-grid">${SKINS.map(s=>`<button class="skin-card ${(v.skinId||'original')===s.id?'active':''}" data-apply-skin="${s.id}"><span class="skin-sample" style="--sample-bg:${s.primary||theme.primary};--sample-gold:${s.accent||theme.accent};--sample-paper:${s.paper||theme.paper}"><strong>章节标题</strong><i></i><i></i></span><b>${s.name}</b><small>${s.description}</small></button>`).join('')}</div>`,'<button class="button" data-close>关闭</button>');
});
$('#modal').addEventListener('click',guarded(e=>{const button=e.target.closest('[data-apply-skin]');if(!button)return;const v=current();if(v.locked)throw new Error('请先解锁方案');change(()=>applySkin(v,button.dataset.applySkin,THEMES.find(t=>t.id===v.id)));closeModal();renderInspector();toast('已应用皮肤，可点击撤销恢复');}));
function renderLayerList(){if(!state)return;const selected=selectedLayer();$('#delete-layer-toolbar').disabled=!selected||current().locked||layerState(current(),selected.id).locked;const query=$('#layer-search').value.trim().toLowerCase();$('#layer-list').innerHTML=orderedLayers(state,current()).reverse().filter(l=>l.name.toLowerCase().includes(query)).map(l=>{const s=layerState(current(),l.id);return `<button data-layer-select="${esc(l.id)}" class="layer-row ${layerSelection===l.id?'active':''} ${s.hidden?'is-hidden':''}"><span>${l.kind==='text'?'T':'▧'}</span><span>${esc(l.name)}</span><small>${s.locked?'锁定':s.hidden?'隐藏':''}</small></button>`}).join('');}
function getLayerCopy(l){if(!l.field||l.itemId)return textForLayer(state,current(),l.id)||'';if(['answer','caption'].includes(l.field))return state.document.blocks.find(b=>b.id===l.blockId)?.[l.field]||'';if(l.custom)return current().customLayers.find(x=>x.id===l.id).text;if(l.field==='block')return state.document.blocks.find(b=>b.id===l.blockId)?.text||'';if(['title','subtitle','intro','outro'].includes(l.field))return state.document[l.field]||'';return textForLayer(state,current(),l.id)??({brand:'魂师名人堂\nCHAMPIONS INTERVIEW',edition:'全大陆魂师精英赛 · 第二期',bottom:current().id==='a'?'✦　 荣 耀 专 访　 ✦':current().id==='b'?'THE VOICES BEHIND THE GLORY':'荣耀之外 · 听见每一位魂师'}[l.field]||l.name);}
function layerInspector(){const l=selectedLayer();if(!l)return '<p class="layer-guide">先点选模块编辑内容与留白；展开内部图层后可拖动、缩放文字和素材。</p>';const s=layerState(current(),l.id);const number=(label,key,value,min,max,step=1)=>`<label>${label}<input type="number" data-layer-setting="${key}" value="${value}" min="${min}" max="${max}" step="${step}"></label>`;return `<section class="layer-inspector"><div class="layer-inspector-heading"><h3>${esc(l.name)}</h3><button class="button quiet" id="deselect-layer">×</button></div><p class="hint">${current().id.toUpperCase()} 方案独立图层 · 坐标相对模板初始位置</p>${l.kind==='text'?`<label class="control">${l.field==='title'?'主标题原文（艺术字改字需重新生成）':'图层文案'}<textarea id="layer-copy" rows="3" ${s.locked||current().locked?'disabled':''}>${esc(getLayerCopy(l))}</textarea></label>`:''}<fieldset ${s.locked||current().locked?'disabled':''}>${layerTextControls(l,s)}<div class="layer-numbers">${number('水平偏移 px','x',s.x,-30000,30000)}${number('垂直偏移 px','y',s.y,-60000,60000)}${number('缩放 %','scale',Math.round(s.scale*100),10,500)}${number('不透明度 %','opacity',s.opacity,0,100)}</div></fieldset><div class="layer-order-controls"><span>图层顺序 · 越靠上越在前</span><div class="mini-buttons"><button class="button" data-layer-order="forward">上移一层</button><button class="button" data-layer-order="backward">下移一层</button></div><div class="mini-buttons"><button class="button" data-layer-order="front">置顶</button><button class="button" data-layer-order="back">置底</button></div>${l.kind==='image'?'<button class="button" data-layer-order="below-copy">放到文案 / Logo 下方</button>':''}</div>${l.id.startsWith('frame:')?`<label class="checkbox-row"><input id="move-linked-title" type="checkbox" ${s.moveTitle?'checked':''} ${s.locked||current().locked?'disabled':''}>移动时带上标题文字</label><button class="button" id="align-chapter-title">将标题文字对齐到装饰条</button><p class="hint">拖动选框或上方「拖动」手柄调整位置；不勾选时只移动装饰条。标题停在拖到的位置，自动留白只整理后续正文，不限制向上移动。</p>`:''}<div class="mini-buttons"><button class="button" id="layer-hide">${s.hidden?'显示图层':'隐藏图层'}</button><button class="button" id="layer-lock">${s.locked?'解锁图层':'锁定图层'}</button></div><div class="mini-buttons"><button class="button" id="reset-layer">重置位置 / 大小</button><button class="button" id="layer-undo">撤销</button></div><button class="button danger" id="delete-selected-layer" ${s.locked||current().locked?'disabled':''}>删除此图层</button><p class="hint">支持画布拖动、右下角缩放、方向键微调；Shift + 方向键移动 10 px。</p></section>`;}
function applyLayerPatch(id,patch){const v=current();if(v.locked||layerState(v,id).locked)return;if(!layerCatalog(state,v).some(l=>l.id===id))return;let changes;try{changes=layerPatchSet(v,id,patch);}catch(e){toast(e.message,true);updatePreviews();return;}change(()=>{v.layers||={};Object.assign(v.layers,changes);});renderInspector();}
function focusLayer(id){moduleUI?.exit();layerSelection=id;selection=null;renderLayerList();renderInspector();$('.preview-frame')?.contentWindow.postMessage({type:'focus-layer',id},location.origin);}
$('#inspector-content').addEventListener('click',guarded(e=>{const action=e.target.closest('[data-layer-order]')?.dataset.layerOrder;if(!action||!layerSelection)return;const order=reorderedLayers(state,current(),layerSelection,action);if(JSON.stringify(order)===JSON.stringify(orderedLayers(state,current()).map(l=>l.id)))return;change(()=>current().layerOrder=order);renderInspector();$('#layer-list [data-layer-select="'+CSS.escape(layerSelection)+'"]')?.scrollIntoView({block:'nearest'});toast('图层顺序已调整，可撤销');}));
$('#layer-list').onclick=e=>{const row=e.target.closest('[data-layer-select]');if(row)focusLayer(row.dataset.layerSelect);};$('#layer-search').oninput=renderLayerList;
$('#variant-tabs').onclick=e=>{const t=e.target.closest('[data-variant-tab]');if(t)selectVariant(t.dataset.variantTab);};
$('#canvas-zoom').onchange=scaleFrames;
$('#toggle-left').onclick=()=>{$('.workbench').classList.toggle('hide-left');requestAnimationFrame(scaleFrames);};
$('#focus-canvas').onclick=()=>{const on=$('.workbench').classList.toggle('focus-mode');$('#focus-canvas').textContent=on?'退出专注':'专注画布';requestAnimationFrame(scaleFrames);};
$('#inspector-content').addEventListener('change',e=>{if(e.target.id==='move-linked-title'){applyLayerPatch(layerSelection,{moveTitle:e.target.checked});return;}const key=e.target.dataset.layerSetting;if(!key||!layerSelection)return;const n=Number(e.target.value);if(e.target.value===''||!Number.isFinite(n)){renderInspector();return;}const value=Math.max(Number(e.target.min),Math.min(Number(e.target.max),n));applyLayerPatch(layerSelection,{[key]:key==='scale'?value/100:value});});
$('#inspector-content').addEventListener('input',e=>{if(e.target.id!=='layer-copy')return;const l=selectedLayer();if(!l||current().locked||layerState(current(),l.id).locked)return;change(()=>{if(l.itemId)state.document.blocks.find(b=>b.id===l.blockId).items.find(i=>i.id===l.itemId)[l.itemField]=e.target.value;else if(['answer','caption'].includes(l.field))state.document.blocks.find(b=>b.id===l.blockId)[l.field]=e.target.value;else if(l.custom)current().customLayers.find(x=>x.id===l.id).text=e.target.value;else if(l.field==='block')state.document.blocks.find(b=>b.id===l.blockId).text=e.target.value;else if(['title','subtitle','intro','outro'].includes(l.field))state.document[l.field]=e.target.value;else{current().layers||={};current().layers[l.id]={...layerState(current(),l.id),text:e.target.value};}});outline();updateTypographyStatus();});
$('#inspector-content').addEventListener('click',guarded(async e=>{const id=e.target.closest('button')?.id;if(id==='delete-selected-layer'){deleteSelectedLayer();return;}if(id==='layer-undo'){undo();return;}if(id==='deselect-layer'){layerSelection=null;$('.preview-frame')?.contentWindow.postMessage({type:'focus-layer',id:''},location.origin);renderLayerList();renderInspector();return;}const l=selectedLayer();if(!l)return;const v=current(),s=layerState(v,l.id);if(id==='align-chapter-title'&&l.id.startsWith('frame:')){const peer='text:'+l.id.slice(6);if(v.locked||s.locked||layerState(v,peer).locked)throw new Error('请先解锁装饰条和标题文字');change(()=>{v.layers||={};v.layers[l.id]={...s,moveTitle:true};v.layers[peer]={...layerState(v,peer),x:s.x,y:s.y};});renderInspector();return;}if(!['layer-hide','layer-lock','reset-layer','delete-free-layer'].includes(id))return;if(v.locked)throw new Error('请先解锁方案');if(s.locked&&id!=='layer-lock')throw new Error('请先解锁此图层');change(()=>{v.layers||={};if(id==='layer-lock')v.layers[l.id]={...s,locked:!s.locked};if(id==='layer-hide')v.layers[l.id]={...s,hidden:!s.hidden};if(id==='reset-layer')v.layers[l.id]={...s,x:0,y:0,scale:1};if(id==='delete-free-layer'&&l.custom){v.customLayers=v.customLayers.filter(x=>x.id!==l.id);delete v.layers[l.id];layerSelection=null;}});renderInspector();}));
function newLayerPosition(){const scale=Number($('.preview-frame')?.dataset.scale)||1;return {x:40,y:Math.round($('#canvases').scrollTop/scale+80)};}
function addFreeLayer(value){if(current().locked)throw new Error('请先解锁方案');const id='custom-'+crypto.randomUUID();change(()=>{current().customLayers||=[];current().layers||={};current().customLayers.push({id,...value});current().layers[id]={...newLayerPosition(),scale:1,z:5};});layerSelection=id;renderLayerList();renderInspector();}
function addFreeImage(assetId){const a=state.assets.find(a=>a.id===assetId);if(!a)throw new Error('请选择图片素材');addFreeLayer({kind:'image',name:a.name,assetId,width:240});}
$('#add-text-layer').onclick=guarded(()=>{addFreeLayer({kind:'text',name:'自由文字',text:'在右侧编辑这段文字',width:360,fontSize:32,color:'#ffffff'});});
$('#add-image-layer').onclick=guarded(()=>{if(current().locked)throw new Error('请先解锁方案');modal('添加独立图片 / Logo',`<label class="control">选择素材<select id="new-free-image">${assetOptions('')}</select></label><p class="hint">每次添加都是独立图层。可在项目素材中上传透明 PNG，再作为 Logo、角色或装饰添加。</p>`,'<button class="button" id="upload-free-image">上传新图片</button><button class="button primary" id="confirm-free-image">添加图层</button>');});
$('#modal').addEventListener('click',guarded(async e=>{const id=e.target.closest('button')?.id;if(id==='confirm-free-image'){addFreeImage($('#new-free-image').value);closeModal();}if(id==='upload-free-image'){$('#asset-input').click();}}));

async function refineTypography(button){const v=current();if(v.locked)throw new Error('请先解锁方案');const projectId=state.id,variantId=v.id,assetId=v.titleArtAssetId;button.disabled=true;button.textContent='正在清理…';try{await save();const {asset}=await post('/api/projects/'+projectId+'/typography-clean',{variant:variantId,assetId});if(state.id!==projectId)return;state.assets.push(asset);const target=state.variants.find(x=>x.id===variantId);if(!target.locked&&target.titleArtAssetId===assetId&&state.document.title===asset.targetText){change(()=>target.titleArtAssetId=asset.id);await save();toast('已重新提取艺术字，可撤销恢复');}else toast('精修结果已保留为候选');assets();renderInspector();}finally{button.disabled=false;button.textContent='精修抠图 · 清理字内残底';}}

function roleFontControls(v){return [['titleFontId','头图标题字体','跟随章节标题'],['numberFontId','奖励数字字体','跟随正文']].map(([key,label,fallback])=>'<label class="control">'+label+'<select data-role-font="'+key+'"><option value="">'+fallback+'</option>'+[{id:'noto',name:'Noto Sans CJK SC · 预览'},...state.fonts].map(f=>'<option value="'+f.id+'" '+(f.id===v[key]?'selected':'')+'>'+esc(f.name)+'</option>').join('')+'</select></label>').join('');}
$('#inspector-content').addEventListener('change',e=>{const key=e.target.dataset.roleFont;if(['titleFontId','numberFontId'].includes(key)){if(current().locked){toast('请先解锁方案',true);return;}change(()=>current()[key]=e.target.value);}});

function layerTextControls(l,s){if(l.kind!=='text')return '';const a=layerArtwork(state,current(),l.id),legacy=l.id==='hero.title'&&titleArtwork(state,current()).asset;return '<div class="text-layer-controls"><label class="control">文字对齐</label><div class="text-align-buttons">'+[['left','左对齐'],['center','居中'],['right','右对齐']].map(([id,name])=>'<button class="button '+(s.align===id?'active':'')+'" data-text-align="'+id+'" aria-pressed="'+(s.align===id)+'">'+name+'</button>').join('')+'</div><button class="button" id="center-text-layer">文本框在长图中水平居中</button><label class="control">此文字图层字体<select id="layer-font-select"><option value="" '+(!s.fontId?'selected':'')+'>跟随模板字体</option>'+[{id:'noto',name:'Noto Sans CJK SC · 预览'},...state.fonts].map(f=>'<option value="'+f.id+'" '+(s.fontId===f.id?'selected':'')+'>'+esc(f.name)+'</option>').join('')+'</select></label><button class="button quiet" id="add-font">＋ 添加字体文件</button><button class="button primary" id="layer-ai-style">✦ AI 生成新的文字样式</button>'+(a.asset||legacy?'<button class="button" id="layer-native-text">切回可编辑文字 / 应用字体</button><p class="hint">当前显示 AI 艺术字图片；选择字体后切回文字即可看到字体效果。</p>':'')+(a.stale?'<p class="font-warning">文案已变化，旧样式已停用，请重新生成。</p>':'')+'<p class="hint">对齐、字体仅修改当前图层。AI 样式先预览再采用，原文保留。</p></div>';}
function layerTypographyDialog(){const l=selectedLayer(),v=current();if(!l||l.kind!=='text')throw Error('请先选择文字图层');if(v.locked||layerState(v,l.id).locked)throw Error('请先解锁方案或图层');if(!boot.aiConfigured)throw Error('请先配置图像生成服务');const text=textForLayer(state,v,l.id);if(!text?.trim()||text.length>100)throw Error('AI 艺术字支持 1–100 个字符，请选择标题或短句');const ref=selectedTypographyReference(v);modal('AI 新文字样式 · '+l.name,'<label class="control">本次生成的文案<textarea readonly rows="3">'+esc(text)+'</textarea></label><label class="control">参考字效<select id="typography-reference">'+state.assets.filter(a=>a.role!=='typography-raw').map(a=>'<option value="'+a.id+'" '+(a.id===ref?.id?'selected':'')+'>'+esc(a.name)+'</option>').join('')+'</select></label><div id="modal-reference-preview">'+referencePreview(ref)+'</div><button class="button" id="modal-upload-reference">＋ 上传字效参考</button><label class="control">新样式方向<textarea id="typography-prompt" rows="3" placeholder="例如：银白金属、细长字形，保持一行，减少装饰"></textarea></label><p class="hint">使用已配置图像服务，仅发送本段文案与参考图。结果为透明艺术字图片；生成后核对文字再采用。</p>','<button class="button" data-close>取消</button><button class="button primary" id="run-layer-typography" data-layer="'+esc(l.id)+'" data-variant="'+v.id+'" data-project="'+state.id+'">生成候选</button>');}
function layerTypographyPreview(a,variant=state.selected){const v=state.variants.find(v=>v.id===variant),text=v&&textForLayer(state,v,a.targetLayerId),usable=a.role==='typography'&&text===a.targetText;modal('文字样式候选','<div class="typography-preview"><img src="'+a.url+'" alt="AI 文字样式候选"></div><label class="control">文案原文<textarea readonly>'+esc(a.targetText)+'</textarea></label><p class="hint">'+(usable?'核对文字后，采用到生成时选择的图层。':a.role==='typography-raw'?esc(a.extractError||'尚未提取透明背景，不能采用。'):'图层已删除或文案已变化，候选已保留，请重新生成。')+'</p>'+(usable?'<label class="checkbox-row"><input id="layer-art-checked" type="checkbox">已逐字核对，文字正确</label>':''),'<button class="button" data-close>暂不采用</button>'+(usable?'<button class="button primary" id="adopt-layer-typography" data-id="'+a.id+'" data-variant="'+variant+'">采用到原文字图层</button>':''));}
$('#inspector-content').addEventListener('click',guarded(e=>{const t=e.target.closest('button');if(!t||!layerSelection)return;if(t.dataset.textAlign)applyLayerPatch(layerSelection,{align:t.dataset.textAlign});if(t.id==='center-text-layer')$('.preview-frame')?.contentWindow.postMessage({type:'center-layer',id:layerSelection},location.origin);if(t.id==='layer-ai-style')layerTypographyDialog();if(t.id==='layer-native-text'){const v=current(),id=layerSelection;if(v.locked||layerState(v,id).locked)throw Error('请先解锁');change(()=>{v.layers||={};v.layers[id]={...layerState(v,id),artAssetId:''};if(id==='hero.title')v.titleArtAssetId='';});renderInspector();}}));
$('#inspector-content').addEventListener('change',e=>{if(e.target.id==='layer-font-select'&&layerSelection)applyLayerPatch(layerSelection,{fontId:e.target.value});});
$('#modal').addEventListener('click',guarded(async e=>{const t=e.target.closest('button');if(!t)return;if(t.id==='run-layer-typography'){if(state.id!==t.dataset.project)throw Error('工程已切换，请重新选择图层');const layerId=t.dataset.layer,variant=t.dataset.variant,projectId=state.id,assetId=$('#typography-reference').value,prompt=$('#typography-prompt').value;if(!assetId)throw Error('请先上传参考图片');await save();t.disabled=true;try{const job=await post('/api/projects/'+projectId+'/ai',{kind:'typography',variant,layerId,assetId,prompt});closeModal();const a=await poll(job);if(state.id===projectId)layerTypographyPreview(a,variant);}finally{t.disabled=false;}}if(t.id==='adopt-layer-typography'){if(!$('#layer-art-checked').checked)throw Error('请先逐字核对并勾选确认');const a=state.assets.find(a=>a.id===t.dataset.id),v=state.variants.find(v=>v.id===t.dataset.variant);if(!a||!v)throw Error('候选或方案不存在');change(()=>adoptLayerArtwork(state,v,a.targetLayerId,a.id));closeModal();renderInspector();await save();toast('已采用新文字样式，原文保留，可撤销');}}));
